abstract class Transport { abstract double calFare(int km); }
class Bus extends Transport  { double calFare(int km) { return 1.0 + 0.1 * km; } }
class Taxi extends Transport { double calFare(int km) { return 3.0 + 0.5 * km; } }
// added later:
class Tricycle extends Transport { double calFare(int km) { return 2.0 * km; } }

public class Main {
    static double total(Transport[] trips, int km) {
        double sum = 0;
        for (Transport t : trips) sum += t.calFare(km);
        return sum;
    }
    public static void main(String[] args) {
        Transport[] trips = { new Bus(), new Taxi(), new Tricycle() };
        System.out.println(total(trips, 10));
    }
}

class Employee {
    private int hours = 45;
    // shared helper used by BOTH departments
    private int regularHours() {
        return Math.min(hours, 44);   // HR changed 40 -> 44
    }
    // owned by Finance: overtime paid at 15/h
    int calculatePay() {
        return regularHours() * 10 + (hours - regularHours()) * 15;
    }
    // owned by HR
    int reportHours() { return regularHours(); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println(new Employee().calculatePay());
    }
}

