import java.util.List;
public class Main {
    static <T extends Comparable<T>> T best(List<T> items) {
        T best = items.get(0);
        for (T x : items)
            if (x.compareTo(best) > 0) best = x;
        return best;
    }
    public static void main(String[] args) {
        System.out.println(best(List.of("pear", "apple", "fig")));
        System.out.println(best(List.of(4, 11, 7)));
    }
}

